using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Non-static class: HttpClient and ILogger are constructor-injected by DI
/// and do NOT appear in the tool schema exposed to LLMs.
/// </summary>
[McpServerToolType]
public class UserApiTools(HttpClient httpClient, ILogger<UserApiTools> logger)
{
    [McpServerTool, Description("Get a user by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The user's numeric ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var user = await httpClient.GetFromJsonAsync<User>(
            $"/users/{userId}", cancellationToken);
        return $"Name: {user!.Name}, Email: {user.Email}, Company: {user.Company?.Name}";
    }

    [McpServerTool, Description("List all users. Returns names and emails.")]
    public async Task<string> ListUsers(CancellationToken cancellationToken = default)
    {
        var users = await httpClient.GetFromJsonAsync<List<User>>(
            "/users", cancellationToken);
        return string.Join("\n", users!.Select(u => $"[{u.Id}] {u.Name} <{u.Email}>"));
    }

    [McpServerTool(ReadOnly = true), Description("Search users by name substring.")]
    public async Task<string> SearchUsers(
        [Description("Name or partial name to search for")] string query,
        CancellationToken cancellationToken = default)
    {
        var users = await httpClient.GetFromJsonAsync<List<User>>(
            "/users", cancellationToken);
        var matches = users!
            .Where(u => u.Name.Contains(query, StringComparison.OrdinalIgnoreCase))
            .ToList();
        return matches.Count == 0
            ? "No users found."
            : string.Join("\n", matches.Select(u => $"[{u.Id}] {u.Name} <{u.Email}>"));
    }
}

// DTOs for the JSONPlaceholder API
public record User(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("company")] Company? Company);

public record Company(
    [property: JsonPropertyName("name")] string Name);

