using ApiMcpServer.Tools;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// Logs MUST go to stderr — stdout is the MCP JSON-RPC transport.
builder.Logging.AddConsole(o => o.LogToStandardErrorThreshold = LogLevel.Trace);

// Register a named HttpClient with base address for the API.
// DI will inject this into UserApiTools via constructor injection.
builder.Services.AddHttpClient<UserApiTools>(client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

// Wire up the MCP server with stdio transport and discover tools.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithTools<UserApiTools>();

await builder.Build().RunAsync();

